def get_sample_resume(profile_type: str) -> str:
    """
    Get a sample resume by profile type.

    Args:
        profile_type: One of senior_engineer, data_scientist, junior_frontend,
                     product_manager, entry_data_analyst, career_changer

    Returns:
        Resume text
    """
    return SAMPLE_RESUMES.get(profile_type, SAMPLE_RESUME_SENIOR_ENGINEER)


def get_all_sample_resumes() -> dict:
    """
    Get all sample resumes.

    Returns:
        Dictionary of all sample resumes
    """
    return SAMPLE_RESUMES
